// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock is the time source used by the limiter.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// TokenBucket is a concurrency-safe token bucket.
type TokenBucket struct {
	mu       sync.Mutex
	capacity float64
	tokens   float64
	rate     float64 // tokens per second
	last     time.Time
	clock    Clock
}

// New creates a full bucket. capacity must be > 0, ratePerSecond must be > 0,
// and clock must not be nil.
func New(capacity int, ratePerSecond float64, clock Clock) (*TokenBucket, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: clock is required")
	}
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive")
	}
	if ratePerSecond <= 0 {
		return nil, errors.New("ratelimit: rate must be positive")
	}
	return &TokenBucket{
		capacity: float64(capacity),
		tokens:   float64(capacity),
		rate:     ratePerSecond,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// NewDefault creates a bucket using the system clock.
func NewDefault(capacity int, ratePerSecond float64) (*TokenBucket, error) {
	return New(capacity, ratePerSecond, realClock{})
}

// AllowN consumes n tokens if available. n <= 0 is a no-op returning true.
func (b *TokenBucket) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refillLocked()
	if float64(n) > b.capacity {
		return false
	}
	if b.tokens >= float64(n) {
		b.tokens -= float64(n)
		return true
	}
	return false
}

// Allow consumes one token.
func (b *TokenBucket) Allow() bool { return b.AllowN(1) }

// Tokens returns the current available token count.
func (b *TokenBucket) Tokens() float64 {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refillLocked()
	return b.tokens
}

func (b *TokenBucket) refillLocked() {
	now := b.clock.Now()
	elapsed := now.Sub(b.last).Seconds()
	if elapsed <= 0 {
		return
	}
	b.tokens += elapsed * b.rate
	if b.tokens > b.capacity {
		b.tokens = b.capacity
	}
	b.last = now
}
