// ratelimit_test.go
package ratelimit

import (
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func newFakeClock() *fakeClock {
	return &fakeClock{t: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
}

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.t
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.t = c.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	clock := newFakeClock()
	tests := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"nil clock", 5, 1, nil, true},
		{"zero capacity", 0, 1, clock, true},
		{"negative capacity", -1, 1, clock, true},
		{"zero rate", 5, 0, clock, true},
		{"negative rate", 5, -1, clock, true},
		{"valid", 5, 1, clock, false},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			b, err := New(tc.capacity, tc.rate, tc.clock)
			if tc.wantErr && err == nil {
				t.Fatal("expected error, got nil")
			}
			if !tc.wantErr && err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if !tc.wantErr && b == nil {
				t.Fatal("expected bucket, got nil")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	tests := []struct {
		name    string
		cap     int
		rate    float64
		advance time.Duration
		n       int
		want    bool
	}{
		{"initial within capacity", 5, 1, 0, 5, true},
		{"exceed capacity", 5, 1, 0, 6, false},
		{"zero tokens", 5, 1, 0, 0, true},
		{"refill after advance", 5, 1, 3 * time.Second, 3, true},
		{"insufficient after partial refill", 5, 1, 1 * time.Second, 2, false},
		{"refill capped at capacity", 5, 1, 10 * time.Second, 5, true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			clock := newFakeClock()
			b, err := New(tc.cap, tc.rate, clock)
			if err != nil {
				t.Fatal(err)
			}
			clock.Advance(tc.advance)
			if got := b.AllowN(tc.n); got != tc.want {
				t.Fatalf("AllowN(%d) = %v, want %v", tc.n, got, tc.want)
			}
		})
	}
}

func TestAllowNConcurrent(t *testing.T) {
	clock := newFakeClock()
	b, err := New(100, 1, clock)
	if err != nil {
		t.Fatal(err)
	}
	var allowed atomic.Int32
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if b.Allow() {
				allowed.Add(1)
			}
		}()
	}
	wg.Wait()
	if allowed.Load() != 100 {
		t.Fatalf("allowed = %d, want 100", allowed.Load())
	}
}
